window.REPORT_PRELOAD_CACHE["BTI.html"] = {"version":"fa6e04755d92384d66acd643b55528c393c1997d8278cddee89c9d8af48ccda7","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>英美烟草 British American Tobacco (NYSE: BTI / LSE: BATS) 深度研究报告：从传统烟草现金牛到 Velo 驱动的无烟尼古丁复利巨头</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            btiblue: {\n              400: '#38BDF8',\n              500: '#0284C7',\n              600: '#0369A1',\n            },\n            emerald: {\n              400: '#34D399',\n              500: '#10B981',\n              600: '#059669',\n            },\n            teal: {\n              400: '#22D3EE',\n              500: '#06B6D4',\n              600: '#0891B2',\n            },\n            amber: {\n              400: '#FBBF24',\n              500: '#F59E0B',\n              600: '#D97706',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微上移 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(2, 132, 199, 0.25) 0%, rgba(16, 185, 129, 0.08) 100%);\n      border-left: 3px solid #38BDF8;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-btiblue-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-btiblue-500 via-emerald-500 to-teal-400 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-btiblue-400 to-emerald-500 flex items-center justify-center font-extrabold text-navy-950 text-xs shadow\">\n        BTI\n      </div>\n      <div>\n        <div class=\"text-[11px] text-btiblue-400 font-semibold tracking-wider uppercase\">NYSE: BTI · LSE: BATS</div>\n        <div class=\"text-sm font-bold leading-tight\">英美烟草深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">BTI 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球必需消费与新型尼古丁研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (H1 26 / FY27E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-btiblue-400 via-btiblue-500 to-emerald-500 flex items-center justify-center text-navy-950 font-extrabold text-base shadow-lg shadow-btiblue-500/25\">\n            BTI\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-btiblue-400 bg-btiblue-500/15 px-2 py-0.5 rounded\">NYSE: BTI · LSE: BATS</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">英美烟草深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          全球传统烟草现金牛 · Velo 口含烟高增与无烟转型复利巨头\n        </p>\n      </div>\n\n      <!-- 股票实时快照徽章 -->\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">参考股价 / 市值</span>\n          <span class=\"font-mono font-bold text-white\">$61.45 <span class=\"text-slate-400\">/ ~$132.5B</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2026 H1 无烟增速</span>\n          <span class=\"font-mono font-bold text-emerald-400\">+18.0% <span class=\"text-btiblue-400\">(Velo +66%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">远期估值与回报</span>\n          <span class=\"font-mono font-bold text-amber-400\">~12.0x P/E · 总回报 ~6.8%</span>\n        </div>\n      </div>\n\n      <!-- 七大核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-btiblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-btiblue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-btiblue-500 to-emerald-500 hover:from-btiblue-600 hover:to-emerald-600 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 font-bold border border-btiblue-500/30\">评级：买入 / 防御复利核心配置</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026–2030 无烟转型与估值重估</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NYSE: BTI · LSE: BATS</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景科技电光蓝点阵纹理 -->\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#38BDF8 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-btiblue-500/20 border border-btiblue-400/40 text-btiblue-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-emerald-400 animate-pulse\"></span>\n              <span>CORE THESIS · 美国薄荷醇禁令警报解除 × Velo 口含烟暴增 66% × ~6.8% 免预扣税股东总回报</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              英美烟草 British American Tobacco (NYSE: BTI) 深度研究报告：从传统烟草现金牛到 Velo 驱动的无烟尼古丁复利巨头\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              历经高负债压制、美国资产减值及监管阴霾后，BTI 在 2025–2026 年迎来<strong class=\"text-white\">基本面修复与估值重估（Re-rating）</strong>双重拐点。2025 年初美国正式撤回薄荷醇（Menthol）禁令提案保住核心利润池；2026 上半年集团固定汇率营收增长 <strong class=\"text-white\">+2.9%</strong>，调整后营业利润率提升至 <strong class=\"text-emerald-400\">43.7% (+30 bps)</strong>，调整后摊薄 EPS 增长 <strong class=\"text-btiblue-400\">+7.9%</strong>。\n              无烟新型品类整体大增 <strong class=\"text-white\">+18.0%（占收比达 19.8%）</strong>，其中 <strong class=\"text-emerald-400\">Velo 口含尼古丁袋暴增 +66%</strong>。叠加净杠杆率回归 2.0x–2.5x 健康区间、5.35% 零预扣税股息与 £13 亿回购，<strong class=\"text-amber-400\">12.0x 远期 P/E</strong> 较菲利普莫里斯（PM，23.0x）仍具显著折价与配置吸引力。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">政策最大尾部风险出清</div>\n                <div class=\"text-white font-semibold\">美国撤回 FDA 薄荷醇卷烟禁令提案，稳固贡献约 30% 营业利润的 Newport 等核心现金牛</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">第二增长曲线盈利放量</div>\n                <div class=\"text-emerald-400 font-semibold\">无烟消费者达 3,500 万，Velo H1 暴增 +66%，预计 2030 年单品牌营收剑指 £43 亿</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">高确定性现金回报壁垒</div>\n                <div class=\"text-btiblue-400 font-semibold\">英国 ADR 享 0% 股息预扣税优势，5.35% 股息率叠加 £13 亿回购构筑 ~6.8% 综合回报</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>总市值 & 参考股价</span>\n              <span class=\"p-1.5 rounded-lg bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 6l3 1m0 0l-3 9a5.002 5.002 0 006.001 0M6 7l3 9M6 7l6-2m6 2l3-1m-3 1l-3 9a5.002 5.002 0 006.001 0M18 7l3 9m-3-9l-6-2m0-2v2m0 16V5m0 16H9m3 0h3\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$132.5B</span>\n              <span class=\"text-xs font-bold text-btiblue-600 dark:text-btiblue-400 bg-btiblue-500/15 px-2 py-0.5 rounded\">$61.45/ADS</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              52 周股价区间 $52.06–$67.30，随着降债达标与无烟放量，估值逐步脱离极端困境折价。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>无烟新型品类营收增速</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">+18.0%</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">占总营收 19.8%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              2026 H1 Velo 口含烟暴增 +66%，新型品类跨越盈亏平衡点后品类贡献利润率持续扩张。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>调整后营业利润率 & 现金转化</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">43.7%</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">OCF 转化 &gt;95%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              2026 H1 营业利润率同比提升 30 bps，固定汇率下调整后摊薄 EPS 稳健增长 +7.9%。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>远期估值 & 股东总回报</span>\n              <span class=\"p-1.5 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~12.0x</span>\n              <span class=\"text-xs font-bold text-amber-600 dark:text-amber-400 bg-amber-500/15 px-2 py-0.5 rounded\">总回报 ~6.8%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              含 5.35% 免预扣税股息率（季息 ~$0.8349/ADS）及 2026 年 £13 亿股份回购注销计划。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-btiblue-600 dark:text-btiblue-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：传统烟草现金牛托底，Velo 领衔无烟第二曲线放量</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">2026 H1 固定汇率营收 +2.9% · 无烟新型品类占比升至 19.8%</span>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图切换面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2027E 集团营收结构演进（可燃烟草 vs 新型无烟品类）</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">新型无烟品类（New Categories）占总营收比重由 2022 年 10.5% 稳步迈向 2027E ~23.4%</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-btiblue-600 dark:text-btiblue-400 shadow-sm transition cursor-pointer\">视图A：营收结构演进</button>\n                <button onclick=\"switchBizChart('h1_growth')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：2026 H1 增速拆解</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解核心洞察 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业基本面三大结构性拐点</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">超强提价权对冲传统卷烟销量自然衰减</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      2026 H1 传统可燃烟销量虽同比下滑 4.7%，但依靠全球品牌组合提价与价格组合优化（Price/Mix +6.8%），板块营收依然实现 <strong>+2.1%</strong> 正增长，持续充当集团自由现金流底座。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Velo Plus 引爆美国口含烟，驱动无烟业务高质量盈利</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      现代口含烟（Velo）H1 营收暴增 <strong>+66%</strong>。升级版 <em>Velo Plus</em> 凭借湿法缓释体验在美国市场份额翻倍爬坡，推动集团无烟消费者总数达 <strong>3,500 万</strong>。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">美国严打非法一次性电子烟，合规龙头 Vuse 边际复苏</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      2025 年底至 2026 年美国 DOJ 与 FDA 多部门联合升级边境查扣与零售清剿执法，有效遏制非法调味电子烟泛滥，推动 Vuse 上半年恢复 <strong>+5.3%</strong> 正增长。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">2026–2030 中期增长算法</span>\n              <span class=\"font-bold text-btiblue-600 dark:text-btiblue-400\">营收 +3%~5% · 调整后 EPS +5%~8%</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 五大业务与资产分部详细卡片矩阵 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- 分部 1：传统可燃烟草 (跨两列) -->\n          <div class=\"md:col-span-2 report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-btiblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <div class=\"flex items-center space-x-2\">\n                <span class=\"px-2.5 py-1 rounded-md bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 text-xs font-bold\">核心现金牛底座 · 营收占比 ~80.2%</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+2.1% YoY (固定汇率)</span>\n              </div>\n              <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">全球四大旗舰品牌矩阵</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 传统可燃烟草（Combustibles：Newport / Dunhill / Kent / Lucky Strike / Pall Mall）</h3>\n            <div class=\"mt-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">美国市场企稳 & 薄荷醇禁令正式撤回</div>\n                <p class=\"leading-relaxed\">\n                  美国市场拥有 Newport（全美第一薄荷醇卷烟）、Natural American Spirit（超高端有机烟）及 Camel。2025 年 1 月美国正式撤回 FDA 薄荷醇禁令提案，彻底保住贡献集团约 30% 营业利润的核心利润池。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">美洲与欧亚新兴市场（AME & APMEA）定价引擎</div>\n                <p class=\"leading-relaxed\">\n                  在欧洲、拉美、中东及亚太地区，Lucky Strike 与 Pall Mall 精准承接中端消费需求，凭借极低的价格敏感度持续提价，源源不断为集团分红与无烟研发提供百亿英镑级现金流。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 分部 2：现代口含烟 Velo -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">头号成长引擎 · +66.0% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-emerald-600 dark:text-emerald-400\">2030E £4.3B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 现代口含尼古丁袋（Velo）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                稳居欧洲现代口含烟绝对龙头（市占率超 60%）；升级产品 <em>Velo Plus</em> 在美国市场高速抢占份额。管理层预计 2030 年全球口含烟规模将翻近三倍至 £110 亿，Velo 单品牌目标剑指 <strong>£43 亿</strong>。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold\">\n              高毛利、高复购 · 估值重估第一驱动力\n            </div>\n          </div>\n\n          <!-- 分部 3：雾化电子烟 Vuse -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">合规雾化龙头 · +5.3% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">全美市占第一</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 雾化电子烟（Vuse Alto / Go）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                手握稀缺的美国 FDA PMTA 营销授权（含薄荷醇口味授权）。随着美国联邦与各州目录法（Directory Laws）铺开并严查非法一次性电子烟，合规封闭式换弹需求稳步回流。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              执法红利逐步兑现 · 盈利贡献持续提升\n            </div>\n          </div>\n\n          <!-- 分部 4：加热不燃烧 glo -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">转型短板承压 · -12.0% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-rose-600 dark:text-rose-400\">HNB 份额受挤压</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 加热不燃烧制品（glo）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                在日本与欧洲等核心市场直面菲利普莫里斯 IQOS Iluma 的强势专利与用户心智壁垒压制，叠加渠道去库存影响，上半年营收下滑 12%，高端新机 <em>glo Hilo</em> 仍处爬坡验证期。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-rose-600 dark:text-rose-400\">\n              直面 IQOS 垄断 · 高端化破局仍需观察\n            </div>\n          </div>\n\n          <!-- 分部 5：战略股权与去杠杆缓冲 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-amber-500/15 text-amber-600 dark:text-amber-400 text-xs font-bold\">隐蔽资产安全垫 · 高流动性</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">ITC 战略持股</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. 印度 ITC Limited 战略股权缓冲</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                此前通过部分减持印度消费与烟草巨头 ITC 股权成功回笼超 <strong>$20 亿</strong>资金加速降债与重启回购；目前剩余持有的逾 20% ITC 股权市值依然庞大，提供极强的资产负债表机动性。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold\">\n              分享印度人口红利 · 资本配置灵活蓄水池\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与四重核心护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：成瘾定价权、监管壁垒与全球渠道霸权</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽阔 (Wide Moat · 全球地域最均衡的跨国尼古丁寡头)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重护城河深度解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 护城河 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">成瘾性消费与抗周期超强定价权</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                尼古丁制品具有极高的生理与心理粘性，消费者品牌忠诚度高、需求价格弹性极低（通常在 -0.3 至 -0.5 之间），使 BTI 数十年如一日能够通过每年 <strong>5%–8% 的提价幅度</strong>轻松对冲通胀与销量下滑。\n              </p>\n            </div>\n\n            <!-- 护城河 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">严苛监管壁垒与 FDA PMTA 牌照护城河</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球烟草广告禁令使新玩家无法通过营销建立品牌心智；同时美国 FDA 漫长且耗资数亿美元的 <strong>PMTA 上市前烟草产品申请</strong>制度，实质上为存量合规寡头构筑了难以逾越的法定准入高墙。\n              </p>\n            </div>\n\n            <!-- 护城河 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球百万终端分销与多品类货架统治力</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                业务覆盖逾 <strong>180 个国家和地区</strong>（行业地域分散度第一）。依托传统卷烟掌控的加油站与便利店黄金收银台货架协议，Velo Plus 与 Vuse 能够以极低边际获客成本迅速实现全渠道铺货。\n              </p>\n            </div>\n\n            <!-- 护城河 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">95%–100% 现金转化与 0% 股息预扣税优势</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                极低的资本开支需求造就常年 <strong>95%–100% 的经营现金流转化率</strong>；叠加英国注册 ADR 对非居民通常<strong>免征股息预扣税（0% Withholding Tax）</strong>，较纯美股同行具备显著的税后复利优势。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球烟草三巨头五维竞争力雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">英美烟草 (BTI) vs 菲利普莫里斯 (PM) vs 奥驰亚 (MO)（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-btiblue-600 dark:text-btiblue-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：估值折价近半，攻守平衡性冠绝同业</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-btiblue-500 text-white shadow-sm transition cursor-pointer\">全部阵营</button>\n            <button onclick=\"filterCompetitors('global_ngp')\" data-filter=\"global_ngp\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">全球跨国无烟龙头</button>\n            <button onclick=\"filterCompetitors('us_yield')\" data-filter=\"us_yield\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">北美本土高息</button>\n            <button onclick=\"filterCompetitors('eurasia_val')\" data-filter=\"eurasia_val\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">欧亚价值烟草</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[185px]\">烟草巨头与核心品牌</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">无烟业务营收占比</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">远期市盈率</th>\n                  <th class=\"py-4 px-4 min-w-[155px]\">股息率与预扣税特征</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">营业利润率</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与配置定位评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：英美烟草 BTI 基准 -->\n                <tr data-category=\"core\" class=\"bg-btiblue-500/5 dark:bg-btiblue-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-btiblue-500 text-white text-[10px] font-extrabold\">核心标的</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">英美烟草 (BTI)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Velo / Vuse / Newport / Dunhill</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">19.8% (Velo +66%)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-btiblue-600 dark:text-btiblue-400\">~12.0x</td>\n                  <td class=\"py-4 px-4 font-semibold text-amber-600 dark:text-amber-400\">~5.35% (英国 0% 预扣税)</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">43.7%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>攻守兼备首选：</strong>全球地域最均衡，估值仅为 PM 一半，兼具 5.35% 免税高息、£13亿回购及 Velo 口含烟高增重估弹性。\n                  </td>\n                </tr>\n\n                <!-- 行 2：菲利普莫里斯 PM -->\n                <tr data-category=\"global_ngp\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">菲利普莫里斯国际 (PM)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">IQOS / Zyn / Marlboro(非美)</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-btiblue-500/15 text-btiblue-700 dark:text-btiblue-400\">~40%+ (行业第一)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~23.0x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~3.20% (美股税制/部分80-20豁免)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~40.5%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>行业成长标杆：</strong>手握 IQOS（HNB绝对霸主）与 Zyn（美国口含烟第一）两大王牌，无烟转型最彻底，但 23x P/E 估值溢价已相当饱满。\n                  </td>\n                </tr>\n\n                <!-- 行 3：奥驰亚 MO -->\n                <tr data-category=\"us_yield\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">奥驰亚 (MO)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Marlboro(美国) / on! / NJOY</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">~12% (转型偏慢)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~13.2x</td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">~6.55% (美股 15%-30% 预扣税)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~58.0%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>纯美股高息代表：</strong>100% 集中于美国本土，营业利润率极高但缺乏国际市场缓冲与强力无烟爆款，主要依赖传统万宝路持续提价。\n                  </td>\n                </tr>\n\n                <!-- 行 4：帝国品牌 IMB -->\n                <tr data-category=\"eurasia_val\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">帝国品牌 (IMB / IMBBY)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Winston / Davidoff / blu / Zone</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">~4% - 5% (聚焦传统)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~9.8x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~5.80% (英国 0% 预扣税+大额回购)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~44.0%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>深度价值回购机器：</strong>战略收缩聚焦五大核心可燃烟市场，激进回购注销推升每股收益，但长期缺乏无烟第二曲线估值想象空间。\n                  </td>\n                </tr>\n\n                <!-- 行 5：日本烟草 JT -->\n                <tr data-category=\"eurasia_val\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">日本烟草 (JT / 2914.T)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Mevius / Winston / Ploom X</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">~4% (Ploom X 追赶中)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~13.8x</td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~4.65% (日本股息预扣税 ~15.3%)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~26.5%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>亚欧传统烟稳健巨头：</strong>收购美国 Vector Group 后补强北美低价烟版图，HNB 产品 Ploom X 在日本本土稳步提份额，受日元汇率影响较大。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 配套 Chart.js 横向条形图：五大烟草巨头估值倍数与股息率对比 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球五大烟草巨头：远期市盈率（Forward P/E）与远期股息率（Dividend Yield）对比</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">BTI 以 ~12.0x 合理低估值提供 5.35% 零预扣税股息，且具备同业仅次于 PM 的无烟收入体量</p>\n            </div>\n            <span class=\"text-xs font-semibold text-btiblue-600 dark:text-btiblue-400 bg-btiblue-500/15 px-2.5 py-1 rounded\">估值折价 + 高息复利黄金交汇点</span>\n          </div>\n          <div class=\"relative h-64 w-full\">\n            <canvas id=\"compPeerChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：去杠杆圆满收官，重回 5%–8% EPS 复利走廊</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">净债务/EBITDA 回归 2.0x–2.5x · 远期 P/E ~12.0x</span>\n        </div>\n\n        <!-- 1. 财务健康度四大硬核指标卡 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-btiblue-600 dark:text-btiblue-400 uppercase\">Adjusted Operating Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">43.7%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              2026 H1 同比提升 30 bps；叠加 2026 年 6 月启动的 <strong>Fit2Win</strong> 降本增效与 AI 转型计划，利润率扩张具备持续支撑。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Cash Conversion</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">95% – 100%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              经营现金流转化率连续多年超越 95%，极强的自由现金流生成能力为渐进分红与持续回购提供坚实保障。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Net Debt / EBITDA</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">2.0x – 2.5x</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              历经多年主动降债及减持部分 ITC 股权回笼资金，2026 年底净杠杆率正式回到目标健康走廊中段，财务枷锁解除。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-amber-600 dark:text-amber-400 uppercase\">Total Shareholder Yield</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~6.8% / 年</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              由 <strong>5.35% 远期股息率</strong>（英镑基准连续逾 25 年增长）叠加 2026 全年 <strong>£13 亿</strong>注销式股票回购共同构成。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 财务与估值演进双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2022–2027E 调整后摊薄 EPS 增长、净杠杆率下降与远期 P/E 估值重估轨迹</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">净债务/EBITDA 从 2.89x 稳步降至 ~2.10x，驱动远期市盈率从 8.2x 困境底部稳健修复至 ~12.0x</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-btiblue-600 dark:text-btiblue-400 bg-btiblue-500/15 px-2.5 py-1 rounded\">较 PM (23.0x) 仍折价约 48%</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"valEvolutionChart\"></canvas>\n          </div>\n        </div>\n\n        <!-- 3. 估值体系演进三阶段卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-slate-500\">STAGE 01 · 2022–2024 上半年</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-mono font-semibold\">7.5x–9.0x P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">高息负债、资产减值与禁令恐慌期</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              受高利率压制雷诺并购债务、£273 亿美国传统品牌会计减值暂停回购及 FDA 薄荷醇禁令阴霾冲击，市场按“夕阳价值陷阱”给出极端折价。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-emerald-500/30 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400\">STAGE 02 · 2024 下半年–2025</span>\n              <span class=\"px-2 py-0.5 rounded bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 text-[11px] font-mono font-semibold\">9.5x–11.0x P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">减持 ITC 重启回购与空头逻辑瓦解期</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              果断变现部分 ITC 股权重启可持续回购，叠加 2025 年 1 月美国正式撤回薄荷醇卷烟禁令提案，核心空头叙事瓦解驱动首轮估值修复。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-gradient-to-br from-btiblue-500/10 to-emerald-500/10 border border-btiblue-500/40 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-btiblue-600 dark:text-btiblue-400\">STAGE 03 · 2026 年底当前视角</span>\n              <span class=\"px-2 py-0.5 rounded bg-btiblue-500/20 text-btiblue-700 dark:text-btiblue-300 text-[11px] font-mono font-semibold\">~12.0x Fwd P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">无烟盈利加速与稳健复利重估期</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              重回 3%–5% 营收与 5%–8% EPS 中期增长算法，Velo 暴增 66% 验证第二曲线成色，估值稳步向全球优质必需消费品中枢（13x–15x）靠拢。\n            </p>\n          </div>\n        </div>\n\n        <!-- 华尔街多空分歧对比 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">Velo 超预期 + 回购扩容</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Velo Plus 美国份额持续超预期：</strong>全美口含尼古丁袋渗透率快速提升，Velo 成为紧随 Zyn 之后的最大受益者，高毛利显著拉动集团整体利润率。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>去杠杆达标释放 2027+ 回购空间：</strong>净债务/EBITDA 回到 2.0x–2.5x 后，每年庞大的超额自由现金流与剩余 ITC 股权可支持更大规模回购注销。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>较 PM 仍存在近 50% 估值折价：</strong>随着无烟收入占比在 2027–2028 迈过 25%，12.0x P/E 仍具备向 14x–15x 温和重估的戴维斯双击潜力。</span></li>\n            </ul>\n          </div>\n\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">修复斜率放缓 + HNB 短板</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>极端低估修复最快阶段已过：</strong>股息率已从前两年的 8.5%+ 收敛至 5.35%，后续回报将回归“业绩+股息”的慢牛复利模式，难以重现单年暴涨。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>glo 在加热不燃烧（HNB）赛道持续失血：</strong>HNB 是单客价值最高的新型烟草品类，但 glo 同比下滑 12%，迟迟无法打破 IQOS 垄断。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>消费降级与汇率/诉讼摩擦：</strong>美国低收入烟民转向深度折扣卷烟压制销量；强势英镑造成约 3% EPS 折算逆风，且加拿大子公司现金受诉讼和解锁定。</span></li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-btiblue-600 dark:text-btiblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景估值推演与免税股息复利策略</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：防御型红利底仓 · 紧盯 11x–12.5x 舒适击球区</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 牛市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：14.5x – 15.5x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>Velo 美国口含烟市占率突破 18%+，FDA 铁腕清剿非法电子烟带动 Vuse 重回双位数增长，无烟营收占比提前突破 25%，2027 年回购规模上调至 £20 亿+。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n              含息潜在上行空间：+25% 至 +35%（估值重估+盈利提速）\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-btiblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-btiblue-600 dark:text-btiblue-400\">概率：50%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：12.0x – 13.0x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>公司稳健兑现 3%–5% 有机营收与 5%–8% 调整后 EPS 中期增长算法，传统烟提价平稳对冲销量下滑，维持 5.35% 股息渐进增长及 £13 亿–£15 亿常规回购。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-btiblue-600 dark:text-btiblue-400\">\n              年化稳健综合回报：+11% 至 +14%（EPS增长+免税股息）\n            </div>\n          </div>\n\n          <!-- 熊市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：9.5x – 10.5x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>美国传统卷烟销量加速下滑超 7%，北美现代口含烟爆发激烈促销价格战压缩利润率，叠加英镑大幅升值带来超预期汇兑损益冲击。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              含息潜在回撤：-8% 至 -15%（高股息提供坚实下档保护）\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与机构缓释视角</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">01 · 估值倍数扩张边际放缓风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">深度折价修复红利已兑现大半，预期差门槛抬升</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                股价从前两年低谷大幅反弹后，Forward P/E 已回到 12.0x 合理区间下沿。若后续季度无烟品类增速出现波动，短期估值倍数可能面临盘整消化。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">02 · 加热不燃烧（HNB）赛道掉队风险</span>\n                <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">glo 持续负增长（-12%），难以撼动 IQOS 生态壁垒</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                在利润率丰厚的加热不燃烧市场，glo 在日欧份额持续流失。若新一代高端设备 <em>glo Hilo</em> 未能扭转颓势，BTI 将长期错失 HNB 高端烟民转化红利。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-btiblue-500/10 text-btiblue-600 dark:text-btiblue-400 text-xs font-bold\">03 · 非法雾化竞争与底层消费降级</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">灰色一次性电子烟屡禁不止与低端折扣烟分流</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                尽管美国加强执法，但低成本非法调味电子烟供应链转换迅速，难以彻底清零；同时累积通胀仍促使部分低收入烟民向四线廉价卷烟降级。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 汇率折算逆风与区域诉讼摩擦</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">约 3% 折算汇率逆风及加拿大诉讼和解现金锁定</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                BTI 以英镑编制报表而收入遍及全球，预计 2026 全年面临约 3% 的调整后 EPS 汇率逆风；此外加拿大烟草诉讼和解要求当地传统业务大部分利润优先用于分期赔付。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 机构级仓位配置建议 + 交互式免税股息复利速算小组件 -->\n        <div class=\"bg-gradient-to-r from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 text-white border border-slate-700 shadow-md space-y-6\">\n          <div>\n            <h3 class=\"text-base font-bold text-btiblue-400 mb-4 flex items-center space-x-2\">\n              <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              <span>机构级组合仓位配置纪律与免预扣税股息复利模拟器</span>\n            </h3>\n            <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                <div class=\"font-bold text-white mb-1\">1. 防御红利底仓定位（Core Income）</div>\n                <p class=\"text-slate-300 leading-relaxed\">\n                  在高科技与高波动资产之外，BTI 凭借低 Beta、抗周期现金流与 ~6.8% 综合股东回报，是全球低波红利与跨资产组合理想的<strong>压舱石底仓</strong>。\n                </p>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                <div class=\"font-bold text-emerald-400 mb-1\">2. 非美税务账户 0% 预扣税优享配置</div>\n                <p class=\"text-slate-300 leading-relaxed\">\n                  作为英国 ADR，非美税务居民（如加拿大普通应税/TFSA账户或港澳新加坡投资者）通常享 <strong>0% 股息预扣税</strong>，税后实际到手收益率显著优于 MO 等纯美股高息股。\n                </p>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n                <div class=\"font-bold text-btiblue-400 mb-1\">3. “BTI + PM” 哑铃型行业配置策略</div>\n                <p class=\"text-slate-300 leading-relaxed\">\n                  机构投资者可采用 <strong>60% BTI（高息折价 + Velo 追赶弹性）+ 40% PM（IQOS/Zyn 双霸主成长确定性）</strong> 构建兼顾高现金流与无烟垄断红利的组合。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 交互式股息复利速算小组件 -->\n          <div class=\"pt-5 border-t border-slate-700/80 no-print\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <span class=\"text-xs font-mono uppercase tracking-wider text-amber-400 font-semibold\">DRIP Compounding Simulator · 免预扣税股息再投资速算（起始股息率 5.35%）</span>\n              <label class=\"inline-flex items-center space-x-2 text-xs text-slate-300 cursor-pointer\">\n                <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDripCalc()\" class=\"rounded accent-[#38BDF8] w-3.5 h-3.5 cursor-pointer\">\n                <span>开启股息自动再投资 (DRIP)</span>\n              </label>\n            </div>\n            <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-5 items-center bg-navy-950/60 rounded-xl p-4 border border-slate-800\">\n              <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs\">\n                <div>\n                  <div class=\"flex justify-between text-slate-300 mb-1\">\n                    <span>初始本金</span>\n                    <span id=\"calc-principal-label\" class=\"font-mono font-bold text-white\">$50,000</span>\n                  </div>\n                  <input id=\"calc-principal\" type=\"range\" min=\"10000\" max=\"300000\" step=\"10000\" value=\"50000\" oninput=\"updateDripCalc()\" class=\"w-full accent-[#38BDF8] cursor-pointer\">\n                </div>\n                <div>\n                  <div class=\"flex justify-between text-slate-300 mb-1\">\n                    <span>持有年限</span>\n                    <span id=\"calc-years-label\" class=\"font-mono font-bold text-white\">10 年</span>\n                  </div>\n                  <input id=\"calc-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDripCalc()\" class=\"w-full accent-[#38BDF8] cursor-pointer\">\n                </div>\n                <div>\n                  <div class=\"flex justify-between text-slate-300 mb-1\">\n                    <span>EPS/股价年增</span>\n                    <span id=\"calc-growth-label\" class=\"font-mono font-bold text-emerald-400\">6.5%</span>\n                  </div>\n                  <input id=\"calc-growth\" type=\"range\" min=\"0\" max=\"10\" step=\"0.5\" value=\"6.5\" oninput=\"updateDripCalc()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n                </div>\n              </div>\n              <div class=\"lg:col-span-5 grid grid-cols-3 gap-3 text-center border-t lg:border-t-0 lg:border-l border-slate-800 pt-3 lg:pt-0 lg:pl-4\">\n                <div>\n                  <div class=\"text-[11px] text-slate-400\">期末预估总资产</div>\n                  <div id=\"calc-final-val\" class=\"text-base sm:text-lg font-mono font-extrabold text-emerald-400 mt-0.5\">$158,420</div>\n                </div>\n                <div>\n                  <div class=\"text-[11px] text-slate-400\">期末年免税股息</div>\n                  <div id=\"calc-annual-div\" class=\"text-base sm:text-lg font-mono font-extrabold text-amber-400 mt-0.5\">$7,195</div>\n                </div>\n                <div>\n                  <div class=\"text-[11px] text-slate-400\">成本股息率 (YoC)</div>\n                  <div id=\"calc-yoc\" class=\"text-base sm:text-lg font-mono font-extrabold text-btiblue-400 mt-0.5\">14.39%</div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-btiblue-500/15 text-btiblue-600 dark:text-btiblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选半年度/季度财报中已验证达标的经营指标（勾选状态自动本地持久化保存），动态检验 BTI 估值重估与股息安全性逻辑：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Velo Plus 美国市场份额与口含烟复购率</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">核心成长锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  追踪美国现代口含烟市占率向双位数中段爬坡进度，验证 Velo 维持超高速增长及 2030 年 £43 亿单品牌营收目标路径。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 美国合规电子烟执法成效与 Vuse 销量回流</span>\n                  <span class=\"text-[11px] font-mono text-btiblue-600 dark:text-btiblue-400 font-semibold shrink-0\">边际修复锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测美国 FDA / DOJ 联合查扣非法一次性调味电子烟及各州目录法落地后，Vuse 营收增速能否在 +5.3% 基础上进一步提速。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 净债务 / 调整后 EBITDA 稳守 2.0x–2.5x 走廊</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">资产负债表锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查 2026 年底净杠杆率正式回到 2.0x–2.5x 中段目标区间，确认利息支出占比下降对净利润的释放效应。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 新型无烟品类营收占比向 25%+ 目标迈进</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">转型兑现度</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  当前无烟占比已达 19.8%，持续追踪无烟板块品类贡献利润（Category Contribution）的扩张斜率及 glo Hilo 止跌企稳信号。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 2027 财年股份回购规模扩容信号</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">股东回报催化剂</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  在 2026 年 £13 亿回购基础上，关注降债达标后管理层是否将更多自由现金流或部分 ITC 变现资金倾斜至常态化大额回购。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-btiblue-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Fit2Win 降本增效计划与传统烟定价弹性</span>\n                  <span class=\"text-[11px] font-mono text-btiblue-600 dark:text-btiblue-400 font-semibold shrink-0\">利润率晴雨表</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查传统可燃烟提价能否持续覆盖 4%–5% 的销量自然下滑，并确保集团调整后营业利润率稳居 43.5%–44.5% 高位。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>英美烟草 British American Tobacco (NYSE: BTI / LSE: BATS) 深度研究报告 · 机构研究框架版</span>\n          <span>数据基准：2026 上半年财报及 2026 年 11 月市场一致预期</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开定期财务报告、投资者日指引及全球烟草行业公开调研数据整理生成，旨在提供结构化的产业分析与估值研究框架。报告中涉及的 2026E–2030E 收入结构预测、三情景估值模型及股息再投资复利模拟均基于特定假设推演，不构成任何证券买卖邀约、税务咨询或具体投资建议。英国 ADR 免征股息预扣税规则可能因投资者税务居民身份及券商账户类型而异，请以独立专业顾问意见为准。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与左侧导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-btiblue-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-btiblue-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-btiblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-btiblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. 免预扣税股息再投资 (DRIP) 速算小组件\n    // ==========================================\n    function updateDripCalc() {\n      const principal = parseFloat(document.getElementById('calc-principal').value);\n      const years = parseInt(document.getElementById('calc-years').value, 10);\n      const epsGrowthPct = parseFloat(document.getElementById('calc-growth').value);\n      const drip = document.getElementById('drip-toggle').checked;\n\n      document.getElementById('calc-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n      document.getElementById('calc-years-label').textContent = years + ' 年';\n      document.getElementById('calc-growth-label').textContent = epsGrowthPct.toFixed(1) + '%';\n\n      const initPrice = 61.45;\n      const initYield = 0.0535;\n      const priceGrowth = epsGrowthPct / 100;\n      const divGrowth = epsGrowthPct === 0 ? 0.01 : priceGrowth * 0.70;\n\n      let shares = principal / initPrice;\n      let price = initPrice;\n      let dps = initPrice * initYield;\n      let cashAccumulated = 0;\n\n      for (let y = 1; y <= years; y++) {\n        const annualDiv = shares * dps;\n        price = price * (1 + priceGrowth);\n        if (drip) {\n          const avgBuyPrice = price / (1 + priceGrowth * 0.5);\n          shares += annualDiv / avgBuyPrice;\n        } else {\n          cashAccumulated += annualDiv;\n        }\n        if (y < years) {\n          dps = dps * (1 + divGrowth);\n        }\n      }\n\n      const finalTotal = (shares * price) + cashAccumulated;\n      const endYearDiv = shares * dps;\n      const yoc = (endYearDiv / principal) * 100;\n\n      document.getElementById('calc-final-val').textContent = '$' + Math.round(finalTotal).toLocaleString('en-US');\n      document.getElementById('calc-annual-div').textContent = '$' + Math.round(endYearDiv).toLocaleString('en-US');\n      document.getElementById('calc-yoc').textContent = yoc.toFixed(2) + '%';\n    }\n\n    // ==========================================\n    // 6. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'bti_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略本地存储读取权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略本地存储写入权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 7. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compPeerChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：2022–2027E 营收结构演进（单位：十亿英镑 £B）\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['2022', '2023', '2024', '2025', '2026E', '2027E'],\n          datasets: [\n            {\n              label: '传统可燃烟草及其他 (£B)',\n              data: [24.8, 23.9, 22.2, 21.3, 21.1, 21.2],\n              backgroundColor: '#0284C7',\n              borderRadius: 4,\n            },\n            {\n              label: '新型无烟品类 New Categories (£B)',\n              data: [2.9, 3.3, 3.6, 4.3, 5.4, 6.5],\n              backgroundColor: '#10B981',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => {\n                  const total = ctx.chart.data.datasets.reduce((sum, ds) => sum + ds.data[ctx.dataIndex], 0);\n                  const share = ((ctx.parsed.y / total) * 100).toFixed(1);\n                  return `${ctx.dataset.label}: £${ctx.parsed.y}B (占总营收 ${share}%)`;\n                }\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 32,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '£' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：2026 H1 板块固定汇率同比增速拆解 (%)\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            'Velo 现代口含尼古丁袋',\n            '新型无烟品类整体 (New Categories)',\n            '调整后摊薄 EPS (固定汇率)',\n            'Vuse 雾化电子烟',\n            '集团总营收 (固定汇率)',\n            '传统可燃烟草 (Combustibles)',\n            'glo 加热不燃烧制品'\n          ],\n          datasets: [\n            {\n              label: '2026 H1 固定汇率同比增速 (%)',\n              data: [66.0, 18.0, 7.9, 5.3, 2.9, 2.1, -12.0],\n              backgroundColor: [\n                '#10B981',\n                '#06B6D4',\n                '#F59E0B',\n                '#38BDF8',\n                '#0284C7',\n                '#64748B',\n                '#F43F5E'\n              ],\n              borderRadius: 6,\n              barThickness: 22\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `2026 H1 同比增速: ${ctx.parsed.x > 0 ? '+' : ''}${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              min: -20,\n              max: 75,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-btiblue-600 dark:text-btiblue-400 shadow-sm transition cursor-pointer';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n        titleEl.textContent = '2022–2027E 集团营收结构演进（可燃烟草 vs 新型无烟品类）';\n        subEl.textContent = '新型无烟品类（New Categories）占总营收比重由 2022 年 10.5% 稳步迈向 2027E ~23.4%';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-btiblue-600 dark:text-btiblue-400 shadow-sm transition cursor-pointer';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n        titleEl.textContent = '2026 H1 各核心板块固定汇率同比增速拆解';\n        subEl.textContent = 'Velo 口含烟暴增 +66% 领跑全集团，glo 加热不燃烧下滑 -12% 仍待破局';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '全球地域分散度',\n            '口含烟增长动能',\n            '传统烟定价与现金转化',\n            '估值安全边际与税后股息',\n            '加热不燃烧(HNB)壁垒'\n          ],\n          datasets: [\n            {\n              label: '英美烟草 (BTI)',\n              data: [9.6, 9.2, 9.3, 9.5, 5.2],\n              borderColor: '#0284C7',\n              backgroundColor: 'rgba(2, 132, 199, 0.22)',\n              pointBackgroundColor: '#0284C7',\n              borderWidth: 2.5\n            },\n            {\n              label: '菲利普莫里斯 (PM)',\n              data: [8.8, 9.6, 9.0, 6.2, 9.9],\n              borderColor: '#10B981',\n              backgroundColor: 'rgba(16, 185, 129, 0.15)',\n              pointBackgroundColor: '#10B981',\n              borderWidth: 2.0\n            },\n            {\n              label: '奥驰亚 (MO)',\n              data: [4.2, 6.8, 9.2, 8.2, 3.5],\n              borderColor: '#F59E0B',\n              backgroundColor: 'rgba(245, 158, 11, 0.12)',\n              pointBackgroundColor: '#F59E0B',\n              borderWidth: 1.6,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompPeerChart() {\n      const ctx = document.getElementById('compPeerChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compPeerChartInstance) compPeerChartInstance.destroy();\n      compPeerChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            '英美烟草 (BTI · 攻守平衡核心)',\n            '菲利普莫里斯 (PM · 无烟成长溢价)',\n            '奥驰亚 (MO · 纯美股高息)',\n            '帝国品牌 (IMB · 传统深度价值)',\n            '日本烟草 (JT · 亚欧稳健龙头)'\n          ],\n          datasets: [\n            {\n              label: '远期市盈率 Forward P/E (倍)',\n              data: [12.0, 23.0, 13.2, 9.8, 13.8],\n              backgroundColor: '#0284C7',\n              borderRadius: 5,\n              barThickness: 14\n            },\n            {\n              label: '远期股息率 Dividend Yield (%)',\n              data: [5.35, 3.20, 6.55, 5.80, 4.65],\n              backgroundColor: '#10B981',\n              borderRadius: 5,\n              barThickness: 14\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.datasetIndex === 0\n                  ? `远期市盈率: ${ctx.parsed.x}x`\n                  : `远期股息率: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 25,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 } }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValEvolutionChart() {\n      const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n      valEvolutionChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['2022', '2023', '2024', '2025', '2026E', '2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '调整后摊薄 EPS ($/ADS 折算)',\n              data: [4.52, 4.68, 4.60, 4.78, 5.12, 5.50],\n              backgroundColor: 'rgba(2, 132, 199, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: '净债务 / 调整后 EBITDA 杠杆率 (x)',\n              data: [2.89, 2.65, 2.52, 2.44, 2.28, 2.12],\n              backgroundColor: 'rgba(16, 185, 129, 0.82)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '远期市盈率 Forward P/E (x)',\n              data: [9.4, 8.2, 8.6, 10.4, 12.0, 12.6],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => {\n                  if (ctx.datasetIndex === 0) return `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}`;\n                  return `${ctx.dataset.label}: ${ctx.parsed.y}x`;\n                }\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              min: 0,\n              max: 7,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 } },\n              title: { display: true, text: 'EPS ($/ADS) & 净杠杆倍数 (x)', color: colors.text, font: { size: 11 } }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 0,\n              max: 16,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + 'x' },\n              title: { display: true, text: 'Forward P/E (倍)', color: '#F59E0B', font: { size: 11 } }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompPeerChart();\n      initValEvolutionChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      updateDripCalc();\n      initBizChart();\n      initRadarChart();\n      initCompPeerChart();\n      initValEvolutionChart();\n    });\n  </script>\n</body>\n</html>"};
